import{_ as e,o as i,c as t,ag as l}from"./chunks/framework.BLV0JUXI.js";const g=JSON.parse('{"title":"uni-app 系统教程 · 精通级演进路线图","description":"","frontmatter":{},"headers":[],"relativePath":"ROADMAP.md","filePath":"ROADMAP.md","lastUpdated":1793196275000}'),s={name:"ROADMAP.md"};function a(n,o,r,d,c,u){return i(),t("div",null,[...o[0]||(o[0]=[l('<h1 id="uni-app-系统教程-·-精通级演进路线图" tabindex="-1">uni-app 系统教程 · 精通级演进路线图 <a class="header-anchor" href="#uni-app-系统教程-·-精通级演进路线图" aria-label="Permalink to &quot;uni-app 系统教程 · 精通级演进路线图&quot;">​</a></h1><blockquote><p>基于项目现状（VitePress 1.5 + Vue 3 + Pinia 3 + TS 5.6，11 模块 33 篇教程，自研中文搜索引擎）， 从 <strong>地基自动化 → 核心壁垒 → 闭环演练 → 平台化 → 单端专精 → 混合栈协同 → 工程质量 → 社区生态</strong> 八个阶段， 按依赖关系从底向上推进。每个阶段内的任务可并行，阶段间存在硬依赖。</p></blockquote><hr><h2 id="现状速览" tabindex="-1">现状速览 <a class="header-anchor" href="#现状速览" aria-label="Permalink to &quot;现状速览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>维度</th><th>已具备</th><th>待补充</th></tr></thead><tbody><tr><td>内容</td><td>11 跨端模块 × 3 阶段 = 33 篇 md；nav.ts 为单一数据源</td><td><strong>0 篇单端专精</strong>（H5/小程序/App 特有技术全空白）、版本标注、实战案例深度、图示/图解</td></tr><tr><td>检索</td><td>自研 search.ts（bigram + AND 语义 + 加权评分 + 高亮）</td><td>倒排索引、BM25、拼音、md 全文</td></tr><tr><td>演练</td><td>CodePlayground iframe + 6 个 HTML 演练场；uniapp-demo 独立 HBuilderX 工程</td><td>H5 产物自动发布、双向链接、代码自动注入</td></tr><tr><td>个人化</td><td>收藏夹（Pinia + IndexedDB）、最近阅读</td><td>学习进度、知识图谱、笔记、计划生成</td></tr><tr><td>工程化</td><td>vitest 4 个测试（taxonomy/search/storage/favorites）、sw.js</td><td>CI 全链路、md ↔ nav 校验、代码片段可执行</td></tr><tr><td>生态</td><td>—</td><td>Discussions、RSS、PR 模板、i18n、插件化</td></tr></tbody></table><p><strong>关键诊断</strong>：现有 33 篇教程视角 100% 是&quot;一份代码覆盖四端&quot;的跨端统一策略， 但 uni-app 用户<strong>真实上线前卡壳的 20% 恰恰是单端特有技术</strong>（微信支付、SSR 部署、原生插件、推送、审核发布等）。 官方文档只讲 API，不讲&quot;怎么接入微信支付上线&quot;——这正是单端专精模块的差异化价值。</p><hr><h2 id="phase-0-·-地基自动化-foundation-automation" tabindex="-1">Phase 0 · 地基自动化（Foundation Automation） <a class="header-anchor" href="#phase-0-·-地基自动化-foundation-automation" aria-label="Permalink to &quot;Phase 0 · 地基自动化（Foundation Automation）&quot;">​</a></h2><blockquote><p><strong>目标</strong>：让维护者做一件事（写 nav.ts）就能驱动全站，消除手工同步风险。 <strong>为什么先做</strong>：后续 Phase 的 build 脚本、CI 校验、内容扩展，全部依赖这里打好的地基。 <strong>估算</strong>：2~3 天 · 可立即启动</p></blockquote><h3 id="_0-1-nav-ts-↔-md-frontmatter-自动同步" tabindex="-1">0.1 nav.ts ↔ md frontmatter 自动同步 <a class="header-anchor" href="#_0-1-nav-ts-↔-md-frontmatter-自动同步" aria-label="Permalink to &quot;0.1 nav.ts ↔ md frontmatter 自动同步&quot;">​</a></h3><ul><li><strong>现状</strong>：nav.ts 是 sidebar/catalog/crumbs/allTags 的单一数据源，但 33 个 md 文件的 frontmatter（title/description/tags）需手工维护，容易出现&quot;nav 改了但 md 没更&quot;</li><li><strong>方案</strong>： <ol><li>扩展 <code>modules</code> 里的 <code>CourseItem</code>，把 <code>summary</code> 字段拆成 <code>summary</code>（一句话）+ <code>description</code>（2~3 句用于 frontmatter）</li><li>写 <code>scripts/sync-frontmatter.mjs</code>：读取 nav.ts → 用 gray-matter 解析对应 md → 自动注入/覆盖 frontmatter → 保留 md 正文不动</li><li>支持 <code>--check</code> 模式（CI 用），检测 diff 后返回非零退出码</li></ol></li><li><strong>影响文件</strong>：<code>.vitepress/theme/nav.ts</code>（加 description）、新增 <code>scripts/sync-frontmatter.mjs</code>、所有 <code>guide/**/*.md</code> 的 frontmatter</li><li><strong>依赖</strong>：无</li><li><strong>成功标准</strong>：运行 <code>pnpm run sync:fm</code> 即可完成全站 frontmatter 同步；CI 拦截手工修改</li></ul><h3 id="_0-2-nav-ts-↔-md-完整性-ci-校验" tabindex="-1">0.2 nav.ts ↔ md 完整性 CI 校验 <a class="header-anchor" href="#_0-2-nav-ts-↔-md-完整性-ci-校验" aria-label="Permalink to &quot;0.2 nav.ts ↔ md 完整性 CI 校验&quot;">​</a></h3><ul><li><strong>现状</strong>：<code>tests/taxonomy.test.ts</code> 校验 catalog 长度、sidebarGroups 结构，但不校验 md 文件是否真实存在、frontmatter 是否与 nav 一致</li><li><strong>方案</strong>： <ol><li>扩展 vitest 套件：校验 nav.ts 每个 <code>link</code> 指向的 md 文件必须存在</li><li>校验 md 的 frontmatter.title 必须包含 nav 里的 phaseLabel（如&quot;基础入门&quot;/&quot;进阶应用&quot;/&quot;实战案例&quot;）</li><li>校验 nav 里的 tags 必须非空、allTags 去重后数量一致</li><li>新增 <code>.github/workflows/quality.yml</code>，push 时自动跑 <code>pnpm test</code></li></ol></li><li><strong>影响文件</strong>：<code>tests/taxonomy.test.ts</code>（扩展）、新增 <code>.github/workflows/quality.yml</code>、可能新增 <code>scripts/check-consistency.mjs</code></li><li><strong>依赖</strong>：0.1 完成（否则 frontmatter 永远对不上）</li><li><strong>成功标准</strong>：缺失 md 或 frontmatter 不一致时 CI 红</li></ul><h3 id="_0-3-md-代码片段可执行校验" tabindex="-1">0.3 md 代码片段可执行校验 <a class="header-anchor" href="#_0-3-md-代码片段可执行校验" aria-label="Permalink to &quot;0.3 md 代码片段可执行校验&quot;">​</a></h3><ul><li><strong>现状</strong>：md 里的 <code>js` / </code>ts<code> / ````vue</code> 代码块无法保证能跑通</li><li><strong>方案</strong>： <ol><li>新增 <code>scripts/validate-snippets.mjs</code>，用 <code>markdown-it</code> 提取 md 中所有 fenced code block</li><li>对 JS/TS 块用 <code>tsx</code> + Node 跑一遍（允许 mock <code>uni</code> / <code>wx</code> 全局）</li><li>对 Vue SFC 块做 template 语法检查（用 <code>@vue/compiler-sfc</code>）</li><li>输出报告：哪些 md 的哪些代码块在哪一行报错</li></ol></li><li><strong>影响文件</strong>：新增 <code>scripts/validate-snippets.mjs</code>、可能需要给 uniapp-demo 里的 <code>uni</code> API 写 mock</li><li><strong>依赖</strong>：无（可与 0.1/0.2 并行）</li><li><strong>成功标准</strong>：<code>pnpm run check:snippets</code> 扫描完 33 篇 md，报告零错误</li></ul><h3 id="_0-4-frontmatter-扩展-版本与难度" tabindex="-1">0.4 Frontmatter 扩展：版本与难度 <a class="header-anchor" href="#_0-4-frontmatter-扩展-版本与难度" aria-label="Permalink to &quot;0.4 Frontmatter 扩展：版本与难度&quot;">​</a></h3><ul><li><strong>方案</strong>：在 nav.ts 的 <code>CourseItem</code> 里加两个字段： <ul><li><code>uniVersion: &#39;3.2.0&#39;</code> — 该教程基于哪个 uni-app 版本</li><li><code>difficulty: 1|2|3</code> — 1=入门 / 2=进阶 / 3=实战</li></ul></li><li>由 0.1 的 sync 脚本自动注入到 md frontmatter</li><li>在首页卡片、sidebar 上可选显示版本号（<code>v3.2</code> 小徽章）</li><li><strong>成功标准</strong>：每个 md 顶部都有版本号 + 难度星级</li></ul><hr><h2 id="phase-1-·-搜索引擎升级-the-core-differentiator" tabindex="-1">Phase 1 · 搜索引擎升级（The Core Differentiator） <a class="header-anchor" href="#phase-1-·-搜索引擎升级-the-core-differentiator" aria-label="Permalink to &quot;Phase 1 · 搜索引擎升级（The Core Differentiator）&quot;">​</a></h2><blockquote><p><strong>目标</strong>：把现有全量扫描的 search.ts → 预构建倒排索引 + BM25 + 拼音 + 全文搜索。 这是本教程站最独特的技术壁垒——VitePress 官方 local search 是 minisearch 封装，社区没有面向中文 uni-app 生态的自建搜索引擎。 <strong>估算</strong>：5~7 天 · 核心亮点</p></blockquote><h3 id="_1-1-miniindex-预构建倒排索引" tabindex="-1">1.1 miniindex 预构建倒排索引 <a class="header-anchor" href="#_1-1-miniindex-预构建倒排索引" aria-label="Permalink to &quot;1.1 miniindex 预构建倒排索引&quot;">​</a></h3><ul><li><strong>现状</strong>：每次搜索都对 catalog（33 项）做全量扫描。如果扩展到 200+ 篇就慢了，且搜不到 md 正文</li><li><strong>方案</strong>： <ol><li><code>vitepress buildEnd</code> 钩子（或独立的 <code>scripts/build-index.mjs</code>）读取 nav.ts + 所有 md 前 3 段正文</li><li>用 miniindex（轻量倒排索引库，~5KB gzip）构建倒排列表 + posting list</li><li>生成 <code>public/index.json</code>（或 <code>public/index.js</code>，VitePress 的搜索可以直接用）</li><li>运行时 search.ts 改为 <strong>O(log N) 查询</strong>，不再全量遍历</li></ol></li><li><strong>影响文件</strong>：<code>package.json</code>（加 miniindex 依赖）、<code>.vitepress/theme/utils/search.ts</code>（重写）、可能加 <code>.vitepress/theme/index.ts</code> 的 buildEnd 钩子</li><li><strong>依赖</strong>：0.1（需要从 nav.ts + md 正文取完整语料）</li><li><strong>成功标准</strong>：<code>pnpm run docs:build</code> 后产物里有 index.json；搜索响应 &lt; 50ms</li></ul><h3 id="_1-2-bm25-排序替换手写加权" tabindex="-1">1.2 BM25 排序替换手写加权 <a class="header-anchor" href="#_1-2-bm25-排序替换手写加权" aria-label="Permalink to &quot;1.2 BM25 排序替换手写加权&quot;">​</a></h3><ul><li><strong>现状</strong>：search.ts 里 <code>scoreDoc</code> 是手写加权（标题×6，标签×4，摘要×1），调着调着就不准</li><li><strong>方案</strong>：引入 BM25 公式（k1=1.2, b=0.75），保留 title/tags/moduleTitle/summary 四个 field 的权重因子</li><li><strong>成功标准</strong>：同一查询&quot;拦截器&quot;，BM25 排序结果比手写加权更合理（企业级请求层排在 request.beforeRequest 之前）</li></ul><h3 id="_1-3-拼音模糊匹配" tabindex="-1">1.3 拼音模糊匹配 <a class="header-anchor" href="#_1-3-拼音模糊匹配" aria-label="Permalink to &quot;1.3 拼音模糊匹配&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>构建索引时给每个词额外存一份拼音（用 pinyin-pro，~15KB gzip）</li><li>查询时如果 token 里全是英文/拼音字母（无中文），先走拼音匹配再走中文匹配</li><li>例：&quot;jiajuzuo&quot; → 命中&quot;脚手架&quot;、&quot;request&quot; → 命中所有含 request 的标题/代码</li></ol></li><li><strong>成功标准</strong>：输入&quot;jiajuzuo&quot;能召回&quot;脚手架&quot;；输入&quot;pinia&quot;召回状态管理相关全部</li></ul><h3 id="_1-4-md-全文索引-含代码片段" tabindex="-1">1.4 md 全文索引（含代码片段） <a class="header-anchor" href="#_1-4-md-全文索引-含代码片段" aria-label="Permalink to &quot;1.4 md 全文索引（含代码片段）&quot;">​</a></h3><ul><li><strong>方案</strong>：索引语料从&quot;title + tags + summary&quot;扩展为： <ul><li>md 正文全部段落（除去 fenced code block）</li><li>fenced code block 里的变量名/API 名（如 <code>addInterceptor</code>、<code>navigateTo</code>）作为额外 boost 词</li></ul></li><li><strong>成功标准</strong>：搜&quot;addInterceptor&quot;能命中&quot;5.2 进阶应用：路由拦截、鉴权守卫&quot;</li></ul><h3 id="_1-5-搜索历史-热门推荐" tabindex="-1">1.5 搜索历史 + 热门推荐 <a class="header-anchor" href="#_1-5-搜索历史-热门推荐" aria-label="Permalink to &quot;1.5 搜索历史 + 热门推荐&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>CatalogExplorer.vue 顶部加一个&quot;大家都在搜&quot;横条：从 nav.ts 的 allTags 里取 top 10（或 IndexedDB 记录 hits 排序）</li><li>IndexedDB 存用户搜索历史（最近 10 条），下拉输入框时可见</li></ol></li><li><strong>成功标准</strong>：检索页打开即显示&quot;大家都在搜：拦截器 / Pinia / 分包 / 虚拟列表&quot;</li></ul><hr><h2 id="phase-2-·-demo-深度集成-close-the-tutorial-code-loop" tabindex="-1">Phase 2 · Demo 深度集成（Close the Tutorial-Code Loop） <a class="header-anchor" href="#phase-2-·-demo-深度集成-close-the-tutorial-code-loop" aria-label="Permalink to &quot;Phase 2 · Demo 深度集成（Close the Tutorial-Code Loop）&quot;">​</a></h2><blockquote><p><strong>目标</strong>：消除 uniapp-demo（独立 HBuilderX 工程）与 VitePress 教程之间的墙，让读者&quot;点一下就能看到跨端代码跑起来&quot;。 <strong>估算</strong>：4~6 天</p></blockquote><h3 id="_2-1-uniapp-demo-h5-自动构建发布" tabindex="-1">2.1 uniapp-demo H5 自动构建发布 <a class="header-anchor" href="#_2-1-uniapp-demo-h5-自动构建发布" aria-label="Permalink to &quot;2.1 uniapp-demo H5 自动构建发布&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>CI 里加 <code>uni build -p h5</code> 步骤（需要 DCloud 官方 CLI 或 npx @dcloudio/uvm 安装）</li><li>产物发布到 <code>public/demo/&lt;module&gt;/&lt;page&gt;/</code> 目录</li><li>CodePlayground 组件改为 iframe 嵌入真实构建产物（不是 source HTML）</li></ol></li><li><strong>影响文件</strong>：<code>uniapp-demo/</code>（可能调整目录结构以支持 CLI 构建）、新增 <code>.github/workflows/build-demo.yml</code></li><li><strong>依赖</strong>：0.1（教程和 demo 路径需要对齐）</li><li><strong>成功标准</strong>：CI push 后 <code>public/demo/04-api/basics-request/</code> 下有真实可访问的 H5 产物</li></ul><h3 id="_2-2-md-↔-demo-源码双向链接" tabindex="-1">2.2 md ↔ demo 源码双向链接 <a class="header-anchor" href="#_2-2-md-↔-demo-源码双向链接" aria-label="Permalink to &quot;2.2 md ↔ demo 源码双向链接&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>扩展 nav.ts 的 <code>CourseItem</code> 加 <code>demoPath?: string</code> 字段（如 <code>&#39;pages/request/request.vue&#39;</code>）</li><li>sync-frontmatter 脚本把 demoPath 注入 md frontmatter</li><li>写 VitePress 自定义组件 <code>DemoLink.vue</code>：在每个 practice.md 底部渲染&quot;查看对应源码 → GitHub 跳转链接&quot;</li></ol></li><li><strong>成功标准</strong>：每篇 practice.md 末尾有一个链接，指向 uniapp-demo 仓库里对应源码的具体文件 + 具体行号</li></ul><h3 id="_2-3-自动代码示例注入" tabindex="-1">2.3 自动代码示例注入 <a class="header-anchor" href="#_2-3-自动代码示例注入" aria-label="Permalink to &quot;2.3 自动代码示例注入&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>在 uniapp-demo 的 .vue 文件里加注释标记：<code>// tutorial:04-api-basics-request-start</code> 和 <code>// tutorial:04-api-basics-request-end</code></li><li>写 build 脚本扫描这些标记，提取片段，注入到 md 的对应位置（Frontmatter 里加 <code>demoSnippet: &#39;04-api-basics-request&#39;</code>）</li><li>VitePress 自定义容器 <code>:::demo-snippet</code> 渲染提取的代码</li></ol></li><li><strong>依赖</strong>：2.1、2.2</li><li><strong>成功标准</strong>：改了 uniapp-demo 里的代码 → 教程里的代码示例自动同步，不复制粘贴</li></ul><h3 id="_2-4-在线-uni-app-编译器-进阶-·-可选" tabindex="-1">2.4 在线 uni-app 编译器（进阶 · 可选） <a class="header-anchor" href="#_2-4-在线-uni-app-编译器-进阶-·-可选" aria-label="Permalink to &quot;2.4 在线 uni-app 编译器（进阶 · 可选）&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>接入 DCloud uniCloud 编译 API（需要后端 serverless 函数）</li><li>CodePlayground 升级为：左侧编辑 uni-app .vue，右侧实时预览编译后的 H5 产物</li></ol></li><li><strong>依赖</strong>：2.1 必须先跑通、后端能力</li><li><strong>成功标准</strong>（如果做）：用户在浏览器里写 uni-app 代码，点&quot;运行&quot;就能看到效果</li></ul><hr><h2 id="phase-3-·-学习平台化-from-docs-to-learning-platform" tabindex="-1">Phase 3 · 学习平台化（From Docs to Learning Platform） <a class="header-anchor" href="#phase-3-·-学习平台化-from-docs-to-learning-platform" aria-label="Permalink to &quot;Phase 3 · 学习平台化（From Docs to Learning Platform）&quot;">​</a></h2><blockquote><p><strong>目标</strong>：让用户&quot;用&quot;教程而不是&quot;看&quot;教程——有进度管理、依赖导航、个人笔记。 <strong>估算</strong>：5~7 天 · 与 Phase 1/2 可部分并行</p></blockquote><h3 id="_3-1-学习进度持久化" tabindex="-1">3.1 学习进度持久化 <a class="header-anchor" href="#_3-1-学习进度持久化" aria-label="Permalink to &quot;3.1 学习进度持久化&quot;">​</a></h3><ul><li><strong>现状</strong>：ReadTracker 只记录&quot;读过哪些&quot;；没有&quot;完成哪些&quot;</li><li><strong>方案</strong>： <ol><li>IndexedDB 里加一个 <code>progress</code> store，记录每个 <code>link</code> 的状态：<code>&#39;reading&#39; | &#39;done&#39; | &#39;skipped&#39;</code> + 完成时间戳</li><li>DocToolbar.vue 加一个&quot;标记已完成 ✅&quot;按钮（就在现有收藏按钮旁边）</li><li>首页 learning-path.md 渲染模块进度条（&quot;模块一 3/3 完成&quot;）</li></ol></li><li><strong>依赖</strong>：无（可与 Phase 1 并行）</li><li><strong>成功标准</strong>：切换浏览器后进度仍在；首页学习路径有可视化进度</li></ul><h3 id="_3-2-知识图谱-模块依赖图" tabindex="-1">3.2 知识图谱 / 模块依赖图 <a class="header-anchor" href="#_3-2-知识图谱-模块依赖图" aria-label="Permalink to &quot;3.2 知识图谱 / 模块依赖图&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>写 build 脚本扫描 nav.ts 的 tags，用标签交叉出现频率构造模块间有向图（08-perf 的&quot;分包加载&quot;标签 ↔ 07-adapt 的&quot;平台分支&quot;标签 → 连一条边）</li><li>自动生成 Mermaid graph，嵌入 learning-path.md</li><li>效果：读者一眼看到&quot;模块七 ← 模块三 ← 模块二 ← 模块一&quot;的前置关系</li></ol></li><li><strong>成功标准</strong>：learning-path.md 顶部有一个 Mermaid 依赖图，能看出学习顺序建议</li></ul><h3 id="_3-3-学习计划生成器" tabindex="-1">3.3 学习计划生成器 <a class="header-anchor" href="#_3-3-学习计划生成器" aria-label="Permalink to &quot;3.3 学习计划生成器&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>前端交互：勾选&quot;我想 3 周内掌握跨端实战&quot; → 选择每天可投入时间（15/30/60 分钟）</li><li>算法：根据 3.2 依赖图做拓扑排序 + 按模块难度加权分配天数</li><li>输出：21 天甘特式计划，每天几篇 + 对应 demo + 预计时长 + 完成打勾</li></ol></li><li><strong>依赖</strong>：3.1（进度要持久化）、3.2（依赖图）</li><li><strong>成功标准</strong>：用户勾选项后 3 秒内生成一份个性化学习计划，可导出 Markdown</li></ul><h3 id="_3-4-段落级笔记-高亮" tabindex="-1">3.4 段落级笔记 / 高亮 <a class="header-anchor" href="#_3-4-段落级笔记-高亮" aria-label="Permalink to &quot;3.4 段落级笔记 / 高亮&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>用户选中正文段落 → 右键菜单&quot;添加笔记&quot;</li><li>IndexedDB 存笔记数组（pageLink + 段落锚点 + 用户笔记文本 + 时间戳）</li><li>新页面 <code>notes.md</code> 汇总所有笔记，支持按模块筛选 + 导出 Markdown</li></ol></li><li><strong>成功标准</strong>：选中一段文字加笔记后，下次回到该页段落有虚线标记 + hover 显示笔记内容</li></ul><hr><h2 id="phase-4-·-工程质量体系-engineering-quality" tabindex="-1">Phase 4 · 工程质量体系（Engineering Quality） <a class="header-anchor" href="#phase-4-·-工程质量体系-engineering-quality" aria-label="Permalink to &quot;Phase 4 · 工程质量体系（Engineering Quality）&quot;">​</a></h2><blockquote><p><strong>目标</strong>：从&quot;个人维护&quot;到&quot;学术级严谨&quot;——每篇教程有版本、代码可跑、多语言可达。 <strong>估算</strong>：3~5 天</p></blockquote><h3 id="_4-1-内容版本矩阵" tabindex="-1">4.1 内容版本矩阵 <a class="header-anchor" href="#_4-1-内容版本矩阵" aria-label="Permalink to &quot;4.1 内容版本矩阵&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>0.4 已经在每个 md frontmatter 加了 <code>uniVersion</code>，现在扩展： <ul><li>教程首页底部显示&quot;本教程基于 uni-app 3.2.0 + Vue 3.5 + Vite 5&quot;</li><li>新增 <code>versions.json</code> 维护多版本文档入口（如 uni-app 3.0 / 3.2 差异对照）</li><li>升级时：每篇 md 加 <code>deprecatedFrom</code> / <code>supersededBy</code> 字段</li></ul></li><li>侧边栏顶部 badge 显示当前站点覆盖的 uni-app 版本</li></ol></li><li><strong>成功标准</strong>：首页明确标注 uni-app 版本号，版本升级时有迁移对照页</li></ul><h3 id="_4-2-ci-全链路校验矩阵" tabindex="-1">4.2 CI 全链路校验矩阵 <a class="header-anchor" href="#_4-2-ci-全链路校验矩阵" aria-label="Permalink to &quot;4.2 CI 全链路校验矩阵&quot;">​</a></h3><ul><li><strong>现状</strong>：<code>.github</code> 目录还不存在，没有 CI</li><li><strong>方案</strong>： <ol><li><code>.github/workflows/quality.yml</code>（push 触发）： <ul><li>pnpm install + test + typecheck</li><li>Phase 0 的 <code>pnpm run sync:fm --check</code> + <code>pnpm run check:snippets</code></li><li>Phase 1 的 <code>pnpm run docs:build</code>（确保构建成功）</li></ul></li><li><code>.github/workflows/deploy.yml</code>（main 分支 push 触发）： <ul><li>docs:build → 产物发布到 GitHub Pages</li><li>同时跑 uniapp-demo H5 构建 → 发布到 Pages 的 <code>/demo/</code> 子路径</li></ul></li></ol></li><li><strong>依赖</strong>：Phase 0（脚本都得先写好）、Phase 2（如果同时部署 demo）</li><li><strong>成功标准</strong>：PR 打开后自动跑全链路，红/绿一目了然</li></ul><h3 id="_4-3-i18n-国际化-英文骨架" tabindex="-1">4.3 i18n 国际化（英文骨架） <a class="header-anchor" href="#_4-3-i18n-国际化-英文骨架" aria-label="Permalink to &quot;4.3 i18n 国际化（英文骨架）&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>用 VitePress 内置 locale 机制，新建 <code>en-US/</code> 目录（每个 md 一份英文骨架，先翻标题和摘要，正文后续补）</li><li>nav.ts 拆成 <code>nav.zh.ts</code> / <code>nav.en.ts</code>，或用 frontmatter 的 <code>title_en</code> 字段</li><li>导航栏加语言切换按钮（已有 <code>--vp-locales</code> 支持）</li></ol></li><li><strong>成功标准</strong>：站点右下角有 🌐 切换按钮，点一下看到英文标题 + 英文摘要</li></ul><h3 id="_4-4-lighthouse-ci-性能基线" tabindex="-1">4.4 Lighthouse CI + 性能基线 <a class="header-anchor" href="#_4-4-lighthouse-ci-性能基线" aria-label="Permalink to &quot;4.4 Lighthouse CI + 性能基线&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>加 <code>.github/workflows/lighthouse.yml</code>，用 Lighthouse CI（lhci）对首页和一篇代表性教程页跑审计</li><li>基线目标：首屏 &lt; 2s、JS bundle &lt; 500KB、可访问性 95+</li><li>每次 deploy 后自动生成 Lighthouse 报告并归档</li></ol></li><li><strong>成功标准</strong>：CI 报告显示性能分数，回归时自动告警</li></ul><hr><h2 id="phase-5-·-社区与生态-community-ecosystem" tabindex="-1">Phase 5 · 社区与生态（Community &amp; Ecosystem） <a class="header-anchor" href="#phase-5-·-社区与生态-community-ecosystem" aria-label="Permalink to &quot;Phase 5 · 社区与生态（Community &amp; Ecosystem）&quot;">​</a></h2><blockquote><p><strong>目标</strong>：从 solo 维护 → 开放社区贡献。 <strong>估算</strong>：3~5 天</p></blockquote><h3 id="_5-1-github-discussions-giscus-集成" tabindex="-1">5.1 GitHub Discussions / Giscus 集成 <a class="header-anchor" href="#_5-1-github-discussions-giscus-集成" aria-label="Permalink to &quot;5.1 GitHub Discussions / Giscus 集成&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>在 GitHub 仓库开 Discussions</li><li>每个 md 页面底部挂 Giscus（或 utterances），用 repo discussion 做后端</li><li>教程作者可以在 nav.ts 里给教程加 <code>discussionCategory: &#39;API 调用&#39;</code> 这样的分类</li></ol></li><li><strong>成功标准</strong>：每个教程页底部有评论区，不注册也能看</li></ul><h3 id="_5-2-rss-feed-xml" tabindex="-1">5.2 RSS / feed.xml <a class="header-anchor" href="#_5-2-rss-feed-xml" aria-label="Permalink to &quot;5.2 RSS / feed.xml&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li><code>vitepress buildEnd</code> 钩子扫描所有 md 按 <code>updated</code> 字段排序 → 生成 <code>public/feed.xml</code></li><li>新增 <code>feed.md</code> 页面说明订阅方式</li></ol></li><li><strong>成功标准</strong>：<code>curl https://你的站点/feed.xml</code> 返回合法 RSS</li></ul><h3 id="_5-3-pr-贡献模板-自动校验" tabindex="-1">5.3 PR 贡献模板 + 自动校验 <a class="header-anchor" href="#_5-3-pr-贡献模板-自动校验" aria-label="Permalink to &quot;5.3 PR 贡献模板 + 自动校验&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li><code>.github/PULL_REQUEST_TEMPLATE.md</code>：引导贡献者说明改动范围、是否需要同步 nav.ts、是否加了测试</li><li><code>.github/ISSUE_TEMPLATE/</code>：Bug 报告 / 内容建议 / 功能请求 三种</li><li>CI 里加检查：PR 里改了 md 就必须同步 nav.ts（Phase 0.2 已做）</li></ol></li><li><strong>成功标准</strong>：外部贡献者首次 PR 能在 5 分钟内通过 CI</li></ul><h3 id="_5-4-插件化-npm-发布" tabindex="-1">5.4 插件化 / npm 发布 <a class="header-anchor" href="#_5-4-插件化-npm-发布" aria-label="Permalink to &quot;5.4 插件化 / npm 发布&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>把 <code>search.ts</code>（中文 bigram + BM25 + 拼音）、<code>custom.css</code>（霓虹主题）提炼为独立包： <ul><li><code>@uniapp-tutorial/vitepress-plugin-local-search-zh</code></li><li><code>@uniapp-tutorial/vitepress-theme-neon</code></li></ul></li><li>发布到 npm，附 README + 最小可运行 demo</li><li>在主项目里通过 npm 引用自身插件（dogfooding）</li></ol></li><li><strong>依赖</strong>：Phase 1（搜索成熟了再拆）、Phase 4（CI 链路）</li><li><strong>成功标准</strong>：npm install 即可在任意 VitePress 项目里启用中文搜索引擎和霓虹主题</li></ul><hr><h2 id="phase-6-·-单端专精补全-single-platform-expertise" tabindex="-1">Phase 6 · 单端专精补全（Single-Platform Expertise） <a class="header-anchor" href="#phase-6-·-单端专精补全-single-platform-expertise" aria-label="Permalink to &quot;Phase 6 · 单端专精补全（Single-Platform Expertise）&quot;">​</a></h2><blockquote><p><strong>目标</strong>：填补 H5 / 微信小程序 / App 三端独有技术的知识空白——这是上线前卡壳的&quot;最后一公里&quot;，也是官方文档不覆盖的差异化价值。 <strong>现状诊断</strong>：33 篇已有教程 100% 是&quot;跨端统一&quot;视角，单端独有技术（SSR、微信支付、原生插件、审核发布等）零覆盖。 <strong>核心产出</strong>：新增 <strong>模块十二（H5 专精）</strong> + <strong>模块十三（微信小程序专精）</strong> + <strong>模块十四（App 专精）</strong>，共 9 篇 md（每模块 3 阶段）。 <strong>估算</strong>：10~14 天 · 内容重写为主、脚本少量补充</p></blockquote><h3 id="_6-1-模块十二-·-h5-端专精-guide-12-h5" tabindex="-1">6.1 模块十二 · H5 端专精（<code>guide/12-h5/</code>） <a class="header-anchor" href="#_6-1-模块十二-·-h5-端专精-guide-12-h5" aria-label="Permalink to &quot;6.1 模块十二 · H5 端专精（`guide/12-h5/`）&quot;">​</a></h3><ul><li><strong>为什么新增</strong>：uni-app H5 端独有 SSR/PWA/SEO/CORS/Web API 等，在小程序/App 上完全不存在</li><li><strong>子任务</strong>： <ol><li><strong>12.1 基础入门：uni-app H5 渲染原理与 SPA 路由</strong><ul><li>渲染后的 DOM 结构（<code>&lt;uni-app&gt;</code> 根节点 / 虚拟列表 / 与小程序/App 的本质差异）</li><li>hash vs history 路由模式切换 + nginx/宝塔回退配置</li><li>浏览器 BOM/DOM API（<code>window</code>/<code>document</code>/<code>fetch</code>/<code>IntersectionObserver</code>）在 uni-app 里的使用边界</li><li>H5 端专属条件编译 <code>#ifdef H5</code> 实战</li></ul></li><li><strong>12.2 进阶应用：SSR、PWA 与 SEO</strong><ul><li>uni-app SSR 配置 + 动态 meta（<code>&lt;title&gt;</code>/<code>og:image</code>/<code>canonical</code>）</li><li>PWA 三件套：<code>manifest.json</code> + Service Worker + 桌面图标 + 安装提示</li><li>SEO checklist：sitemap.xml、robots.txt、结构化数据、AMP 适配</li></ul></li><li><strong>12.3 实战案例：企业级 H5 发布（Nginx + CDN + CI/CD）</strong><ul><li>CORS 跨域解决 + Cookie <code>SameSite=None</code> 处理 + HTTPS 证书</li><li>HSTS + CSP + Permissions Policy 安全头</li><li>SSR 首屏 &lt; 1s 优化演练（关键 CSS 内联、图片 lazy、HTTP/2 push）</li></ul></li></ol></li><li><strong>影响文件</strong>：新增 <code>guide/12-h5/{basics,advanced,practice}.md</code>、nav.ts 新增 1 个模块条目</li><li><strong>依赖</strong>：Phase 0（nav.ts ↔ frontmatter 同步、md 完整性校验）</li><li><strong>成功标准</strong>：12.3 提供可运行的 Nginx 配置片段 + CDN 回源策略 + 完整的 CI/CD YAML</li></ul><h3 id="_6-2-模块十三-·-微信小程序端专精-guide-13-mp-weixin" tabindex="-1">6.2 模块十三 · 微信小程序端专精（<code>guide/13-mp-weixin/</code>） <a class="header-anchor" href="#_6-2-模块十三-·-微信小程序端专精-guide-13-mp-weixin" aria-label="Permalink to &quot;6.2 模块十三 · 微信小程序端专精（`guide/13-mp-weixin/`）&quot;">​</a></h3><ul><li><strong>为什么新增</strong>：微信小程序是 uni-app 用户量最大的目标端，但官方文档从不教&quot;怎么上线一个合规的小程序&quot;</li><li><strong>子任务</strong>： <ol><li><strong>13.1 基础入门：uni-app 小程序编译产物与原生差异</strong><ul><li><code>dist/dev/mp-weixin/</code> 目录结构解读（<code>app.json</code>/<code>pages.json</code>/组件映射表）</li><li>原生小程序组件 / API / 配置 与 uni 封装的映射关系对照表</li><li>微信开发者工具 + 真机调试 + 模拟器差异</li></ul></li><li><strong>13.2 进阶应用：微信能力深度集成</strong><ul><li><code>wx.login</code> + <code>code2session</code> + <code>openid</code>/<code>unionid</code> 鉴权体系（uni.login 四端差异）</li><li><strong>微信支付</strong> <code>wx.requestPayment</code>（uni.requestPayment 参数差异、签名、回调）</li><li>订阅消息（一次性/长期）+ 模板 ID 配置 + 后端发送模板</li><li><code>getPhoneNumber</code> 手机号一键登录（2023 年后授权 API 变化）</li><li>小程序分包（微信后台配置 vs uni-app 编译分包，两者同时存在）</li></ul></li><li><strong>13.3 实战案例：从 0 发布一个上线版小程序</strong><ul><li>微信公众平台注册 → AppID → 小程序后台配置（服务器域名、业务域名、隐私协议）</li><li>体验版上传 + 灰度发布 + 全量发布</li><li>隐私合规弹窗 <code>__usePrivacyCheck__</code> + 审核必备清单</li><li>url scheme / 分享跳转（小程序 → H5 → 小程序）</li></ul></li></ol></li><li><strong>影响文件</strong>：新增 <code>guide/13-mp-weixin/{basics,advanced,practice}.md</code>、nav.ts 新增 1 个模块条目</li><li><strong>依赖</strong>：Phase 0、6.1（H5 历史路由知识可复用）</li><li><strong>成功标准</strong>：13.3 给出一份&quot;上线前 checklist&quot;，按清单走完不会因审核被拒</li></ul><h3 id="_6-3-模块十四-·-app-端专精-ios-android-guide-14-app" tabindex="-1">6.3 模块十四 · App 端专精（iOS + Android，<code>guide/14-app/</code>） <a class="header-anchor" href="#_6-3-模块十四-·-app-端专精-ios-android-guide-14-app" aria-label="Permalink to &quot;6.3 模块十四 · App 端专精（iOS + Android，`guide/14-app/`）&quot;">​</a></h3><ul><li><strong>为什么新增</strong>：原生插件、推送、热更新、应用市场上架是 uni-app 变现的最后一公里，社区里没人系统性讲</li><li><strong>子任务</strong>： <ol><li><strong>14.1 基础入门：uni-app App 构建原理</strong><ul><li>云打包 vs 离线打包 vs 原生工程（HBuilderX / Android Studio / Xcode）三种路线对比</li><li>HTML5+ <code>plus</code> API 全景（<code>plus.android.importClass</code> / <code>plus.ios</code> 原生交互）</li><li>证书 / 图标 / 启动页 / SplashScreen 配置清单</li></ul></li><li><strong>14.2 进阶应用：原生插件与 App 运行时能力</strong><ul><li><code>uni.requireNativePlugin</code> 调用极光推送 / 高德地图 / 微信 SDK / 支付宝 SDK</li><li>App 热更新（wgt 包）+ 灰度策略 + 失败回滚</li><li>推送服务接入（极光 / 个推 / Apple Push / 华为 / 小米 / OPPO / vivo 七路）</li><li>生物识别（指纹 / 面容）+ 原生权限声明（iOS Info.plist / Android AndroidManifest.xml）</li></ul></li><li><strong>14.3 实战案例：企业级 App 完整发布流程</strong><ul><li>华为 / 小米 / OPPO / vivo / 三星应用商店上架（每家审核规则差异）</li><li>iOS App Store 审核（隐私合规、ITC-21.5 条款、Guideline 4.2 最小功能）</li><li>崩溃监控（Sentry / Bugly 接入）+ 灰度崩溃告警</li><li>App 版本升级强更 / 弱更策略（<code>uni.getProperty(&#39;AppStore&#39;,&#39;version&#39;)</code>）</li></ul></li></ol></li><li><strong>影响文件</strong>：新增 <code>guide/14-app/{basics,advanced,practice}.md</code>、nav.ts 新增 1 个模块条目</li><li><strong>依赖</strong>：Phase 0、6.2（微信支付的四端差异需要同时参考）</li><li><strong>成功标准</strong>：14.3 有一份&quot;多商店上架 checklist&quot;，按清单走完能在 7 天内上齐主流应用市场</li></ul><h3 id="_6-4-nav-ts-sidebargroups-扩展" tabindex="-1">6.4 nav.ts + sidebarGroups 扩展 <a class="header-anchor" href="#_6-4-nav-ts-sidebargroups-扩展" aria-label="Permalink to &quot;6.4 nav.ts + sidebarGroups 扩展&quot;">​</a></h3><ul><li><strong>方案</strong>： <ol><li>在 nav.ts 的 <code>modules</code> 数组末尾追加三个 <code>CourseModule</code>（slug 分别为 <code>12-h5</code> / <code>13-mp-weixin</code> / <code>14-app</code>）</li><li>每个模块继续保持 <code>basics</code> / <code>advanced</code> / <code>practice</code> 三阶段结构</li><li>各模块的 tags 建议新增：<code>H5</code>、<code>SSR</code>、<code>PWA</code>、<code>SEO</code>、<code>微信支付</code>、<code>订阅消息</code>、<code>原生插件</code>、<code>热更新</code>、<code>应用商店</code>、<code>推送</code> 等</li><li>sync-frontmatter 脚本（Phase 0.1）自动同步 frontmatter，Phase 0.2 CI 自动校验完整性</li></ol></li><li><strong>依赖</strong>：Phase 0.1 必须先完成（否则 nav.ts 扩展后 md frontmatter 无法同步）</li><li><strong>成功标准</strong>：sidebar 左侧菜单出现&quot;模块十二 · H5 端专精&quot;等三个新分组</li></ul><h3 id="_6-5-uniapp-demo-单端分支策略" tabindex="-1">6.5 uniapp-demo 单端分支策略 <a class="header-anchor" href="#_6-5-uniapp-demo-单端分支策略" aria-label="Permalink to &quot;6.5 uniapp-demo 单端分支策略&quot;">​</a></h3><ul><li><strong>方案</strong>：uniapp-demo 仓库里为三个新模块各开独立分支： <ul><li><code>demo-h5</code>：专注 H5 特有组件（SSR 路由守卫 / PWA 注册 / CORS 请求）</li><li><code>demo-mp-weixin</code>：专注微信特有代码（微信支付签名 / code2session / 订阅消息模板调用）</li><li><code>demo-app</code>：专注 App 原生交互（requireNativePlugin 调用极光推送 / plus 原生页面跳转）</li></ul></li><li>分支独立的好处：条件编译块太多时容易把四端代码搅在一起，分拆后单端代码纯绿</li><li><strong>依赖</strong>：Phase 2（demo ↔ md 双向链接）</li></ul><hr><h2 id="phase-7-·-混合栈与跨应用协同-hybrid-stack-cross-app-collab" tabindex="-1">Phase 7 · 混合栈与跨应用协同（Hybrid Stack &amp; Cross-App Collab） <a class="header-anchor" href="#phase-7-·-混合栈与跨应用协同-hybrid-stack-cross-app-collab" aria-label="Permalink to &quot;Phase 7 · 混合栈与跨应用协同（Hybrid Stack &amp; Cross-App Collab）&quot;">​</a></h2><blockquote><p><strong>目标</strong>：填补&quot;跨容器、跨应用、跨技术栈&quot;协同的知识空白——这是 uni-app 用户从&quot;单项目跨端&quot;走向&quot;多项目/多端混合&quot;时必然遇到的架构问题。 <strong>现状诊断</strong>：现有 33 篇教程 + Phase 6 单端专精，全部是&quot;单一 uni-app 工程内的跨端策略&quot;。但真实生产中大量场景涉及：</p><ul><li>uni-app 内嵌原生 SDK（极光/高德/微信）→ requireNativePlugin</li><li>小程序 <code>&lt;web-view&gt;</code> 嵌独立 H5 编辑器 → postMessage 双向通信</li><li>原生 Android/iOS 壳嵌 uni-app 页面 → plus.webview + JSBridge</li><li>H5 拉起小程序、小程序拉起 App → url scheme + 微信开放标签</li><li>小程序 ↔ App 账号体系打通 → unionid + JWT 官方文档只讲 web-view / requireNativePlugin API 签名，<strong>不讲怎么搭混合栈架构</strong>。 <strong>核心产出</strong>：新增 <strong>模块十五 · 混合栈与跨应用协同</strong>（3 篇 md）。 <strong>估算</strong>：5~7 天 · 偏架构与集成实战</li></ul></blockquote><h3 id="_7-1-模块十五-·-混合栈与跨应用协同-guide-15-hybrid" tabindex="-1">7.1 模块十五 · 混合栈与跨应用协同（<code>guide/15-hybrid/</code>） <a class="header-anchor" href="#_7-1-模块十五-·-混合栈与跨应用协同-guide-15-hybrid" aria-label="Permalink to &quot;7.1 模块十五 · 混合栈与跨应用协同（`guide/15-hybrid/`）&quot;">​</a></h3><ul><li><strong>为什么新增</strong>：uni-app 的&quot;混合&quot;场景远比&quot;条件编译&quot;更广义——它是<strong>跨技术栈、跨容器、跨进程</strong>的协同，不是编译期分支</li><li><strong>与现有模块七的边界</strong>： <ul><li>模块七 = &quot;同一份代码，编译期物理剪枝&quot;（单工程、编译时）</li><li>模块十五 = &quot;多来源代码在运行时协同&quot;（跨工程、运行时）</li></ul></li><li><strong>子任务</strong>： <ol><li><strong>15.1 基础入门：混合开发全景与三条武器</strong><ul><li>混合开发 vs 跨端统一 vs 原生混编：三者边界与决策树（何时用哪种）</li><li>三条武器清单： <ul><li><code>web-view</code> 组件（跨 H5 ↔ 小程序/App 容器，运行时 HTML）</li><li><code>plus.webview</code>（原生级 webview 管理，App 端独占）</li><li><code>uni.requireNativePlugin</code>（原生 SDK 桥接，App 端独占）</li></ul></li><li>JSBridge 基础：<code>window.webkit.messageHandlers</code>（iOS）/ <code>plus.webview.evalJS</code>（App）/ <code>wx.miniProgram.postMessage</code>（H5 内嵌小程序）</li></ul></li><li><strong>15.2 进阶应用：跨容器通信与跨端拉起</strong><ul><li><strong>H5 ↔ 小程序</strong>：web-view <code>postMessage</code> + <code>wx-open-launch-weapp</code> 标签拉起 + 小程序跳转其他小程序</li><li><strong>H5 ↔ App</strong>：<code>uni.postMessage</code> + <code>plus.webview.currentWebview()</code> + H5 调原生 <code>plus.android.invoke</code> / <code>plus.ios</code></li><li><strong>App ↔ 原生 SDK</strong>：requireNativePlugin 写一个极光推送完整示例（Android/iOS 双端 plugin 实现 + uni-app 调用端）</li><li><strong>小程序 ↔ App 账号打通</strong>：unionid 体系 + H5 中转登录 + JWT 双端共享</li><li><strong>原生 App ↔ uni-app 页面互跳</strong>：<code>plus.webview.create</code> 从原生壳拉起 uni 页面 + uni 调回原生 Activity/ViewController</li></ul></li><li><strong>15.3 实战案例：三种典型混合栈架构落地</strong><ul><li><strong>方案 A · uni-app App + 原生 SDK</strong>：完整演示 requireNativePlugin 调用高德地图 3D SDK（含 plugin 目录结构、Android .aar 集成、iOS .framework、HBuilderX 打包配置）</li><li><strong>方案 B · 小程序 + 独立 H5 编辑器</strong>：小程序 <code>&lt;web-view&gt;</code> 加载独立 Vue3 编辑器，用户编辑完 <code>postMessage</code> 同步回小程序页面</li><li><strong>方案 C · H5 + 小程序 + App 三端统一登录态</strong>：H5 写 cookie → 小程序 web-view 读取 → App plus.webview 同步，附 JWT + 刷新策略</li></ul></li></ol></li><li><strong>影响文件</strong>：新增 <code>guide/15-hybrid/{basics,advanced,practice}.md</code>、nav.ts 新增 1 个模块条目</li><li><strong>依赖</strong>：Phase 0（nav.ts ↔ frontmatter 同步）、Phase 6（H5/小程序/App 单端知识已具备，混合是在此之上做协同）</li><li><strong>成功标准</strong>：7.3 三个方案每个都给出完整可运行的 demo 代码（含 requireNativePlugin 的 Android/iOS 原生端代码片段）</li></ul><h3 id="_7-2-nav-ts-扩展-新增模块十五" tabindex="-1">7.2 nav.ts 扩展（新增模块十五） <a class="header-anchor" href="#_7-2-nav-ts-扩展-新增模块十五" aria-label="Permalink to &quot;7.2 nav.ts 扩展（新增模块十五）&quot;">​</a></h3><ul><li><strong>方案</strong>：在 Phase 6.4 的基础上，再追加 <code>15-hybrid</code> 模块</li><li><strong>tags 建议</strong>：<code>混合开发</code>、<code>web-view</code>、<code>JSBridge</code>、<code>requireNativePlugin</code>、<code>postMessage</code>、<code>跨端拉起</code>、<code>unionid</code></li><li><strong>依赖</strong>：Phase 0.1（sync-frontmatter）、Phase 6.4（6 个单端/跨端模块已注册，混合模块排在最后）</li><li><strong>成功标准</strong>：sidebar 出现&quot;模块十五 · 混合栈与跨应用协同&quot;</li></ul><h3 id="_7-3-uniapp-demo-混合分支" tabindex="-1">7.3 uniapp-demo 混合分支 <a class="header-anchor" href="#_7-3-uniapp-demo-混合分支" aria-label="Permalink to &quot;7.3 uniapp-demo 混合分支&quot;">​</a></h3><ul><li><strong>方案</strong>：uniapp-demo 开 <code>demo-hybrid</code> 分支，包含： <ul><li><code>plugins/push-plugin/</code>：极光推送原生插件（Android + iOS）</li><li><code>pages/native-map/</code>：调用高德原生 3D 地图的 uni 页面</li><li><code>pages/webview-editor/</code>：内嵌独立 H5 编辑器并 postMessage 同步</li><li>H5 编辑器子目录（独立 Vue3 工程，演示 postMessage 接收端）</li></ul></li><li><strong>依赖</strong>：Phase 6.5（demo-h5 / demo-mp-weixin / demo-app 已跑通）</li><li><strong>成功标准</strong>：<code>demo-hybrid</code> 分支 clone 下来，HBuilderX 打开就能看到三个混合场景</li></ul><hr><h2 id="依赖关系总览" tabindex="-1">依赖关系总览 <a class="header-anchor" href="#依赖关系总览" aria-label="Permalink to &quot;依赖关系总览&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Phase 0 (地基)  ──→  Phase 1 (搜索)  ──→  Phase 2 (Demo)</span></span>\n<span class="line"><span>     │                    │                    │</span></span>\n<span class="line"><span>     ├──→ Phase 3 (平台化) ←──────────────────┘</span></span>\n<span class="line"><span>     │</span></span>\n<span class="line"><span>     ├──→ Phase 6 (单端专精)</span></span>\n<span class="line"><span>     │         │</span></span>\n<span class="line"><span>     │         └──→ Phase 2.1/2.2 (给新模块配套 demo 分支)</span></span>\n<span class="line"><span>     │         │</span></span>\n<span class="line"><span>     │         └──→ Phase 7 (混合栈协同) ← 依赖单端知识作为前提</span></span>\n<span class="line"><span>     │                    │</span></span>\n<span class="line"><span>     │                    └──→ Phase 2.1/2.2 (demo-hybrid 分支)</span></span>\n<span class="line"><span>     │</span></span>\n<span class="line"><span>     Phase 0 ──→ Phase 4 (工程质量) ──→ Phase 5 (社区)</span></span></code></pre></div><p><strong>可并行</strong>：</p><ul><li>Phase 0.3（代码校验）与 Phase 0.1/0.2</li><li>Phase 1 与 Phase 3（Phase 3.1 不依赖搜索升级）</li><li>Phase 1 与 Phase 6/7（写内容不需要搜索引擎升级）</li><li>Phase 0 与 Phase 5（Discussions/RSS/模板不依赖地基）</li><li>Phase 6 内部三个模块可同时开写（6.1 / 6.2 / 6.3 互相无依赖）</li><li>Phase 7 与 Phase 1/2/3 可并行（只要 Phase 6 的单端专精已有初步内容即可）</li></ul><p><strong>硬依赖</strong>：</p><ul><li>Phase 0.1 → Phase 0.2、Phase 0.4、Phase 1.1、Phase 2.2、<strong>Phase 6.4</strong>、<strong>Phase 7.2</strong></li><li>Phase 0.1 + Phase 0.2 + Phase 0.3 → Phase 4.2（CI 校验链）</li><li>Phase 2.1 → Phase 2.3</li><li>Phase 6.4（nav.ts 单端扩展）→ Phase 6.1/6.2/6.3</li><li><strong>Phase 6（单端专精已有）→ Phase 7（混合栈是单端之上的协同）</strong></li><li>Phase 7.2（nav.ts 混合模块注册）→ Phase 7.1 具体 md 写作</li></ul><hr><h2 id="里程碑与交付定义" tabindex="-1">里程碑与交付定义 <a class="header-anchor" href="#里程碑与交付定义" aria-label="Permalink to &quot;里程碑与交付定义&quot;">​</a></h2><table tabindex="0"><thead><tr><th>里程碑</th><th>完成标志</th><th>目标时间</th></tr></thead><tbody><tr><td><strong>M0 · 地基就绪</strong></td><td>nav ↔ frontmatter 自动同步 + CI 拦截不一致 + 代码片段可执行校验</td><td>3 天</td></tr><tr><td><strong>M1 · 搜索革命</strong></td><td>miniindex 预构建 + BM25 + 拼音 + md 全文索引 全部到位</td><td>M0 后 5 天</td></tr><tr><td><strong>M2 · 闭环演练</strong></td><td>uniapp-demo H5 自动发布 + md ↔ demo 双向链接 + 代码自动注入</td><td>M0 后 5 天</td></tr><tr><td><strong>M3 · 学习平台</strong></td><td>进度持久化 + 知识图谱 + 计划生成 + 笔记</td><td>M0 后 7 天（与 M1/M2 并行）</td></tr><tr><td><strong>M4 · 单端补全</strong></td><td>新增模块十二 H5 + 模块十三 微信小程序 + 模块十四 App（9 篇 md）+ nav.ts 对齐</td><td>M0 后 12 天（与 M1/M2/M3 并行）</td></tr><tr><td><strong>M5 · 混合栈补全</strong></td><td>新增模块十五 混合栈与跨应用协同（3 篇 md）+ requireNativePlugin 完整 demo</td><td>M4 后 5 天（可与 M1/M2 并行启动，依赖 M4 有初稿）</td></tr><tr><td><strong>M6 · 工程闭环</strong></td><td>CI 全链路 + Lighthouse + i18n 骨架</td><td>M0+M1+M2 后 5 天</td></tr><tr><td><strong>M7 · 开放生态</strong></td><td>Discussions + RSS + PR 模板 + 插件发布</td><td>持续</td></tr></tbody></table><blockquote><p>内容产出汇总（M0 完成后累计）：<strong>原 11 模块 33 篇 → M4 完成 14 模块 42 篇 → M5 完成 15 模块 45 篇</strong></p></blockquote><hr><h2 id="不在本路线图内-另起炉灶级" tabindex="-1">不在本路线图内（另起炉灶级） <a class="header-anchor" href="#不在本路线图内-另起炉灶级" aria-label="Permalink to &quot;不在本路线图内（另起炉灶级）&quot;">​</a></h2><p>这些不是&quot;扩展&quot;而是&quot;重写&quot;：</p><ul><li><strong>换 Nuxt 3 / Next.js 做前端</strong> — VitePress 满足需求</li><li><strong>自研前端框架</strong> — 过重</li><li><strong>后端 API（Node/Nest）</strong> — 当前离线站零后端体验更好，除非做 Phase 2.4 在线编译器</li><li><strong>小程序 App 双端 UI</strong> — uniapp-demo 已经是 HBuilderX 工程，不需要 VitePress 再渲染 UI</li></ul><hr><blockquote><p><strong>维护约定</strong>：本 ROADMAP.md 随项目进展持续更新。每个 Phase 完成后打 tag（如 <code>v0.5.0-m0</code>）， 里程碑达成后发 Release Notes。所有任务的 PR 标题以 <code>feat(M1):</code> / <code>fix(P0):</code> 等前缀区分。</p></blockquote>',113)])])}const h=e(s,[["render",a]]);export{g as __pageData,h as default};
